-- MARTEX operator data (SYNTHETIC): vessels, voyages, hourly telemetry, alarms.
-- Generated by scripts/data/generate_gulf_voyages.py into data/clean/ (mounted at /seed).
-- Runs automatically on a fresh database; on an existing one run:
--   docker exec martex-db psql -U martex -d martex -f /docker-entrypoint-initdb.d/02_operations.sql

DROP TABLE IF EXISTS alarms, telemetry_hourly, voyages, vessels;

CREATE TABLE vessels (
  vessel_id text PRIMARY KEY, name text, vessel_type text, teu_capacity integer,
  design_speed_kn numeric, loa_m numeric, beam_m numeric, mcr_kw integer, data_origin text
);

CREATE TABLE voyages (
  voyage_id text PRIMARY KEY, vessel_id text REFERENCES vessels(vessel_id),
  destination_unlocode text, destination_name text,
  berth_window_start_utc timestamptz, berth_window_end_utc timestamptz,
  planned_speed_kn numeric, status text, data_origin text
);

CREATE TABLE telemetry_hourly (
  vessel_id text REFERENCES vessels(vessel_id), ts_utc timestamptz,
  latitude numeric, longitude numeric, sog_kn numeric, stw_kn numeric, me_rpm numeric,
  me_load_pct numeric, fuel_tph numeric, exhaust_temp_avg_c numeric,
  exhaust_temp_deviation_c numeric, scavenge_air_temp_c numeric, draft_m numeric,
  distance_to_go_nm numeric, data_origin text,
  PRIMARY KEY (vessel_id, ts_utc)
);

CREATE TABLE alarms (
  vessel_id text REFERENCES vessels(vessel_id), ts_utc timestamptz, system text,
  code text, severity text, message text, data_origin text
);

COPY vessels FROM '/seed/vessels.csv' WITH (FORMAT csv, HEADER true);
COPY voyages FROM '/seed/voyages.csv' WITH (FORMAT csv, HEADER true);
COPY telemetry_hourly FROM '/seed/telemetry_hourly.csv' WITH (FORMAT csv, HEADER true);
COPY alarms FROM '/seed/alarms.csv' WITH (FORMAT csv, HEADER true);
